                     for cc in range(c, c + 3) if grid[rr][cc] != bg]
            if not cells:
                continue
            # Require the candidate square to contain the whole non-bg
            # component, rather than being an arbitrary part of a larger one.
            seen = set()
            stack = [cells[0]]
            while stack:
                x, y = stack.pop()
                if (x, y) in seen or grid[x][y] == bg:
                    continue
                seen.add((x, y))
                for dx, dy in ((1,0),(-1,0),(0,1),(0,-1)):
