                        stack.append((nx, ny))
            if len(seen) != len(cells):
                continue
            if min(x for x, y in seen) != r or max(x for x, y in seen) != r + 2:
                continue
            if min(y for x, y in seen) != c or max(y for x, y in seen) != c + 2:
                continue
